<script setup lang="ts">
const { data, refresh } = await useWorkspace()
const modal = ref(false), busy = ref(false), error = ref('')
const form = reactive({ name: '', description: '' })
const credentials = ref<{ id: string; token: string } | null>(null)
const origin = ref('http://127.0.0.1:3100')
onMounted(() => { origin.value = window.location.origin })
const command = computed(() => credentials.value ? `FORGELABS_URL=${origin.value}\nFORGELABS_WORKER_ID=${credentials.value.id}\nFORGELABS_WORKER_TOKEN=${credentials.value.token}\nSTT_REPO=/absolute/path/to/stt-tamil\nFORGELABS_DATA_ROOT=/absolute/path/to/datasets\nFORGELABS_RUN_ROOT=/absolute/path/to/forgelabs-runs` : '')
async function save() { busy.value = true; error.value = ''; try { credentials.value = await $fetch('/api/servers', { method: 'POST', body: form }); await refresh() } catch (e) { error.value = apiError(e) } finally { busy.value = false } }
async function copy() { try { await navigator.clipboard.writeText(command.value); useNotice().notify('Worker configuration copied') } catch { error.value = 'Select and copy the configuration below.' } }
function close() { modal.value = false; credentials.value = null; form.name = ''; form.description = ''; error.value = '' }
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR INFRASTRUCTURE</span><h1>Compute<span class="title-dot">.</span></h1><p>Bring your GPUs. Keep control of where training happens.</p></div><button class="button primary" @click="modal = true"><AppIcon name="Plus" />Connect server</button></div><div class="info-strip"><AppIcon name="Radio" /><span>Workers connect outward to ForgeLabs. No SSH credentials are stored in the application.</span></div><div v-if="data.servers.length" class="resource-grid"><article v-for="server in data.servers" :key="server.id" class="panel resource-card"><div class="resource-top"><span class="resource-icon"><AppIcon name="Server" :size="25" /></span><StatusBadge :status="isOnline(server) ? 'online' : server.lastSeen ? 'offline' : 'unpaired'" /></div><h2>{{ server.name }}</h2><p>{{ server.description || 'Dedicated training worker' }}</p><div class="hardware-list"><div v-for="(gpu, i) in server.telemetry?.gpus || []" :key="i"><span><AppIcon name="Cpu" :size="15" />{{ gpu.name }}</span><strong>{{ (gpu.memoryUsed / 1024).toFixed(1) }} / {{ (gpu.memoryTotal / 1024).toFixed(0) }} GB</strong><div class="meter"><span :style="{ width: `${Math.min(100, gpu.memoryUsed / Math.max(1, gpu.memoryTotal) * 100)}%` }" /></div><small>{{ gpu.utilization }}% utilization</small></div><div v-if="!server.telemetry?.gpus?.length" class="subtle">GPU inventory appears after the worker connects.</div></div><div class="resource-footer"><span>{{ ago(server.lastSeen) }}</span><span v-if="server.telemetry?.diskFreeGb !== undefined">{{ server.telemetry.diskFreeGb.toFixed(0) }} GB free</span></div><NuxtLink v-if="server.telemetry?.activeRunId" :to="`/runs/${server.telemetry.activeRunId}`" class="text-link">View active run<AppIcon name="ArrowUpRight" :size="15" /></NuxtLink></article></div><section v-else class="panel"><EmptyState icon="Server" title="A home for your training jobs" description="Connect a GPU server to see its hardware, availability, and running experiments."><button class="button secondary" @click="modal = true"><AppIcon name="Plus" :size="16" />Connect your first server</button></EmptyState></section><AppModal v-if="modal" :title="credentials ? 'Your worker is ready to pair' : 'Connect a server'" :subtitle="credentials ? 'Save this token now. It is shown only once.' : 'Give your GPU worker a recognizable name.'" @close="close"><template v-if="credentials"><div class="alert warning">Use a ForgeLabs URL reachable from the GPU server. Localhost only works on the same machine.</div><pre class="code-block">{{ command }}</pre><p class="form-hint">Save these values in an environment file on the worker. From the ForgeLabs checkout, run <code>python3 worker/agent.py --env-file /path/to/worker.env</code> using the stt-tamil Python environment.</p><div class="modal-actions"><button class="button secondary" @click="copy"><AppIcon name="Copy" :size="16" />Copy configuration</button><button class="button primary" @click="close">Done</button></div></template><form v-else @submit.prevent="save"><label class="field">Server name<input v-model="form.name" required minlength="2" maxlength="100" placeholder="e.g. Blackwell workstation" /></label><label class="field">Description <span class="optional">optional</span><textarea v-model="form.description" rows="3" maxlength="500" placeholder="Location, purpose, or hardware notes" /></label><p v-if="error" class="alert error" role="alert">{{ error }}</p><div class="modal-actions"><button type="button" class="button secondary" @click="close">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Creating…' : 'Generate worker token' }}<AppIcon name="ArrowRight" :size="16" /></button></div></form></AppModal></template>
